{"code": "const lines = [
"import tmp.sheaf.xif.paper.S1746FiniteEtaleQuotientsActual",
"",
"open CategoryTheory CategoryTheory.Limits",
"",
"abbrev TestFiniteEtaleAlg (K : Type) [Field K] : Type 1 :=",
"  (CommAlgCat.FiniteEtale.{0} K)ᵒᵖ",
"",
"example (K : Type) [Field K] (G : Type) [Group G] [Finite G] :",
"    HasColimitsOfShape (SingleObj G) (TestFiniteEtaleAlg K) := by",
"  infer_instance"
];
const w = await tools.write({file_path: "tmp/sheaf/xif/paper/_S1746ImportCheck.lean", content: lines.join("\n")});
const r = await tools.pwsh({command: "lake env lean tmp/sheaf/xif/paper/_S1746ImportCheck.lean", description: "Check infer_instance for S1739-style abbrev", timeoutMs: 600000});
console.log(r.stdout.text);
console.log("STDERR:", r.stderr.text.slice(0,10000));
console.log("EXIT", r.exitCode);
", "description": "Check infer_instance for S1739-style abbrev"}

